input.command:
# 1. PROCESS CHECK
Write-Host '--- PROCESS CHECK ---'
Get-Process | Where-Object {$_.ProcessName -match 'claude|anthropic|Code|cursor|windsurf'} | Select-Object ProcessName, Id, StartTime, Path | Format-Table

# 2. ENVIRONMENT CHECK
Write-Host '--- ENVIRONMENT CHECK ---'
Get-ChildItem Env: | Where-Object {$_.Name -match 'ANTHROPIC|CLAUDE|MCP|OPENAI|GEMINI|AI_|LLM_'} | Format-Table Name, Value

# 3. GIT STATUS
Write-Host '--- GIT STATUS ---'
if (Test-Path 'D:\pog2') {
    Set-Location 'D:\pog2'
    git status
    git log --oneline -5
    git diff --name-only
} else {
    Write-Host 'D:\pog2 not found'
}

# 4. GLOBAL NPM CHECK
Write-Host '--- GLOBAL NPM CHECK ---'
npm list -g --depth=0 2>$null | Select-String 'claude mcp anthropic ollama'

# 5. RECENT FILE CHANGES (last 2 hours)
Write-Host '--- RECENT FILE CHANGES ---'
if (Test-Path 'D:\pog2') {
    Get-ChildItem -Path 'D:\pog2' -Recurse -Filter '*.ts' | Where-Object {$_.LastWriteTime -gt (Get-Date).AddHours(-2)} | Select-Object FullName, LastWriteTime, Length | Sort-Object LastWriteTime -Descending | Format-Table
}

# 6. OLLAMA STATE
Write-Host '--- OLLAMA STATE ---'
ollama list 2>$null
ollama ps 2>$null

# 7. CHECK FOR COGNITIVEIMMUNOLOGYEMERGENCY.TS
Write-Host '--- COGNITIVE IMMUNOLOGY CHECK ---'
if (Test-Path 'D:\pog2') {
    Get-ChildItem -Path 'D:\pog2' -Recurse -Filter '*CognitiveImmunology*' | Select-Object FullName, LastWriteTime, Length | Format-Table
}

# 8. GHOSTLIMB.TS CURRENT STATE
Write-Host '--- GHOSTLIMB.TS STATE ---'
if (Test-Path 'D:\pog2\src\limbs\metaphysical\GhostLimb.ts') {
    Get-Content 'D:\pog2\src\limbs\metaphysical\GhostLimb.ts' -TotalCount 50
} else {
    Write-Host 'GhostLimb.ts not found'
}
